// n8n Code Node: Fixed Exact Email Extraction

const item = $input.item.json;
const body = item.body || item;
const message = body.message || {};
const artifact = message.artifact || {};

// Format Transcript into text block
const rawTranscript = artifact.messages || message.transcript || body.transcript || [];
function formatTranscript(messages) {
  if (!messages) return '';
  if (typeof messages === 'string') return messages;
  if (!Array.isArray(messages)) return '';
  return messages
    .filter(m => m && (m.role === 'assistant' || m.role === 'user' || m.role === 'bot'))
    .map(m => `${(m.role === 'assistant' || m.role === 'bot') ? 'AI' : 'User'}: ${m.message || m.content || ''}`)
    .join('\n');
}

const transcriptText = formatTranscript(rawTranscript);

// ---------------- EXTRACTION LOGIC ----------------

// 1. Name Extraction
let name = 'N/A';
const nameMatch = transcriptText.match(/(?:my name is|i am|this is)\s+([a-zA-Z]+)/i) || 
                  transcriptText.match(/AI:\s*Hello\s+([a-zA-Z]+)/i);
if (nameMatch) name = nameMatch[1];

// 2. Location Extraction
let location = 'N/A';
if (/uttora|kustora|uttara/i.test(transcriptText)) {
  location = 'Uttara';
} else if (/gulshan/i.test(transcriptText)) {
  location = 'Gulshan';
} else if (/banani/i.test(transcriptText)) {
  location = 'Banani';
} else if (/dhanmondi/i.test(transcriptText)) {
  location = 'Dhanmondi';
} else if (/bashundhara/i.test(transcriptText)) {
  location = 'Bashundhara';
}

// 3. Property Type & Requirements
let property = 'N/A';
if (/apartment|flat/i.test(transcriptText)) {
  property = 'Apartment';
} else if (/plot|land/i.test(transcriptText)) {
  property = 'Plot';
} else if (/commercial|office/i.test(transcriptText)) {
  property = 'Commercial Space';
}

const bedMatch = transcriptText.match(/(\d+)\s*(?:bed|bedroom)/i);
const washMatch = transcriptText.match(/(\d+)\s*(?:washroom|bath|bathroom)/i);
let propertyDetails = property;
if (bedMatch || washMatch) {
  const beds = bedMatch ? `${bedMatch[1]} Bed` : '';
  const baths = washMatch ? `${washMatch[1]} Bath` : '';
  propertyDetails = `${beds} ${baths} ${property}`.trim();
}

// 4. Budget Extraction
let budget = 'N/A';
const budgetMatch = transcriptText.match(/(?:budget\s*(?:around|is)?\s*)?(\d+(?:\.\d+)?\s*(?:crore|lakh|million|BDT))/i);
if (budgetMatch) {
  budget = budgetMatch[1];
}

// 5. Phone Number Extraction
let phone = 'N/A';
const digitsOnly = transcriptText.replace(/[^0-9]/g, '');
if (digitsOnly.length >= 11) {
  const phoneMatch = digitsOnly.match(/01\d{9}/);
  if (phoneMatch) {
    phone = phoneMatch[0];
  } else {
    phone = digitsOnly.slice(-11);
  }
}

// 6. EXACT EMAIL EXTRACTION
// 6. STRICT & CLEAN EMAIL EXTRACTION (Strips glued phone numbers and filler words)
let email = 'N/A';

let cleanText = transcriptText.toLowerCase()
  .replace(/at\s*the\s*rate/g, '@')
  .replace(/at\s*gmail/g, '@gmail')
  .replace(/dot\s*com/g, '.com')
  .replace(/\s+/g, '');

// Extract standard email format
const rawEmailMatch = cleanText.match(/([a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})/i);

if (rawEmailMatch) {
  let matchedStr = rawEmailMatch[1];

  // 1. Remove trailing domain glitches like .com.ai -> .com
  matchedStr = matchedStr.replace(/\.com\.[a-z]+$/i, '.com');

  // 2. Remove leading digits (Phone number glued to email)
  matchedStr = matchedStr.replace(/^[0-9]+/, '');

  // 3. Remove leading dots or symbols
  matchedStr = matchedStr.replace(/^[.\s\-_]*/, '');

  // 4. Remove spoken filler prefixes (andmyemailis, myemailis, emailis, is, etc.)
  matchedStr = matchedStr.replace(/^(andmyemailis|myemailis|emailis|myemail|email|is)+/i, '');

  // 5. Final pass to strip any remaining leading symbols or digits
  matchedStr = matchedStr.replace(/^[.\s\-_0-9]*/, '');

  // Validate final email format
  const finalEmailMatch = matchedStr.match(/([a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})/i);
  if (finalEmailMatch) {
    email = finalEmailMatch[1];
  }
}

// 7. Site Visit Extraction
let visitSites = 'N/A';
const visitMatch = transcriptText.match(/(tomorrow(?:\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?)?|next\s+[a-z]+\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?|\d{1,2}(?:st|nd|rd|th)?\s+[a-z]+\s+at\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?)/i);
if (visitMatch) {
  visitSites = visitMatch[0];
}

// Date Formatter
function formatDate(dateStr) {
  const d = dateStr ? new Date(dateStr) : new Date();
  return d.toLocaleString('en-US', {
    month: 'numeric',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit',
    hour12: true
  });
}

const intent = `Looking for ${propertyDetails !== 'N/A' ? propertyDetails : property} in ${location} with budget ${budget}`;

return [{
  json: {
    date_time: formatDate(message.createdAt || artifact.createdAt || body.createdAt),
    name: name,
    phone: phone,
    email: email,
    property: propertyDetails,
    budget: budget,
    location: location,
    visit_sites: visitSites,
    intent: intent,
    transcript: transcriptText
  }
}];

